import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 sing-box 兼容吗？","description":"说明如何把 sing-box JSON 配置、订阅、VLESS、Trojan、Hysteria2、TUIC、AnyTLS 节点迁移到 Clash iOS。","frontmatter":{"title":"Clash 与 sing-box 兼容吗？","description":"说明如何把 sing-box JSON 配置、订阅、VLESS、Trojan、Hysteria2、TUIC、AnyTLS 节点迁移到 Clash iOS。","head":[["meta",{"name":"keywords","content":"sing-box iOS,sing-box转Clash,sing-box JSON,mihomo YAML,Hysteria2 iOS,TUIC iOS,AnyTLS iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"如何把 sing-box JSON 配置迁移到 Clash？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Clash 使用 mihomo YAML。优先获取 mihomo 格式订阅，或根据 sing-box 节点与路由参数重新建立 YAML。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"sing-box 节点可以在 Clash 中使用吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以，只要节点使用 Clash 支持的协议、传输方式、TLS、认证方式与参数。常见的 VLESS、Trojan、Hysteria2、TUIC 与 AnyTLS 均受支持。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility/sing-box.md","filePath":"zh/guide/compatibility/sing-box.md","lastUpdated":1785318168000}`),a={name:`zh/guide/compatibility/sing-box.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与-sing-box-兼容吗" tabindex="-1">Clash 与 sing-box 兼容吗？ <a class="header-anchor" href="#clash-与-sing-box-兼容吗" aria-label="Permalink to “Clash 与 sing-box 兼容吗？”">​</a></h1><p><strong>节点协议可以复用，配置统一使用 mihomo YAML。</strong></p><p><a href="https://sing-box.sagernet.org/configuration/" target="_blank" rel="noreferrer">sing-box 使用 JSON 配置</a>，Clash 使用 mihomo YAML。迁移时可以提取需要的节点、路由与 DNS 意图，并在 mihomo YAML 中重新建立。</p><h2 id="哪些-sing-box-节点可以继续使用" tabindex="-1">哪些 sing-box 节点可以继续使用？ <a class="header-anchor" href="#哪些-sing-box-节点可以继续使用" aria-label="Permalink to “哪些 sing-box 节点可以继续使用？”">​</a></h2><p>只要参数匹配，sing-box 用户常用的这些协议可以在 Clash 中继续使用：</p><ul><li>VLESS；</li><li>Trojan；</li><li>Shadowsocks；</li><li>Hysteria2；</li><li>TUIC；</li><li>AnyTLS；</li><li>WireGuard；</li><li>SSH。</li></ul><p>完整范围请参阅<a href="/clash.md/zh/guide/protocols">支持的协议</a>。</p><h2 id="怎么迁移最省事" tabindex="-1">怎么迁移最省事？ <a class="header-anchor" href="#怎么迁移最省事" aria-label="Permalink to “怎么迁移最省事？”">​</a></h2><ol><li>优先向服务商获取 mihomo / Clash 格式的订阅。</li><li>如果只有 <code>ss://</code>、<code>vless://</code>、<code>trojan://</code> 等分享链接，请先转换成 mihomo YAML，或在 Clash 的节点编辑器中按链接参数重新添加。</li><li>单节点分享链接可以作为参数来源，整理成 YAML 或手动填写。</li><li>重新建立原来只存在于 sing-box JSON 中的路由与 DNS 规则。</li></ol><h2 id="迁移时需要重新配置" tabindex="-1">迁移时需要重新配置 <a class="header-anchor" href="#迁移时需要重新配置" aria-label="Permalink to “迁移时需要重新配置”">​</a></h2><ul><li>将 sing-box JSON 结构整理为 mihomo YAML；</li><li>将 <code>route</code>、<code>dns</code>、<code>inbounds</code>、<code>outbounds</code> 中需要的能力映射到 Clash；</li><li>为实验性选项选择 Clash 中对应的稳定能力；</li><li>在 Clash 中设置界面与 Apple 系统选项。</li></ul><p>协议、传输、TLS、认证和其他参数与 Clash 支持范围一致时，同一台服务器即可直接使用。</p><p>返回<a href="/clash.md/zh/guide/compatibility">兼容性总览</a>。</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};